theorem select_integrable (R S : ℝ≥0) {f g : SampleSpace → ℝ}
    (hf : Integrable f gaussianProduct) (hg : Integrable g gaussianProduct) :
    Integrable (select R S f g) gaussianProduct

theorem bounded_comp_memLp (u : CoefficientSpace) {φ : ℝ → ℝ}
    (hc : Continuous φ) {A : ℝ} (hA : ∀ x, ‖φ x‖ ≤ A) :
    MemLp (fun ω => φ (firstChaosEmbedding u ω)) 2 gaussianProduct

theorem physicalNoise_tendsto {f : ℕ → TimeHilbert} {h : TimeHilbert}
    (hf : Tendsto f atTop (𝓝 h)) :
    Tendsto (fun n => physicalNoise (f n)) atTop (𝓝 (physicalNoise h))
